"""Template for the generated Kaggle task files.

memtrap/build_tasks.py fills the placeholders. The generated file is
self-contained: the items, the reply parser (memtrap/parse.py) and the
scoring (memtrap/score.py) are inlined, so the Kaggle notebook needs nothing
from this repository.
"""

TEMPLATE = '''# %% [markdown]
# # {title}
#
# {description}
#
# Part of MemoryTrap Bench: {repo_url}
# Generated by memtrap/build_tasks.py from cases/cases.json and
# cases/truth.json. Do not edit by hand.

# %%
import json
import random
import re
import time

import kaggle_benchmarks as kbench
import pandas as pd

CONDITION = {condition!r}
ITEM_LIMIT = {item_limit!r}  # None runs every item; the pilot uses a small number
REPAIR_MESSAGE = "Your reply could not be read. Reply with the JSON object only, nothing else."
ATTEMPTS = 3  # a nested evaluate() runs each item once, so transient proxy errors are retried here
RETRY_SLEEP = 10  # seconds, times the number of errors so far
MAX_OUTPUT_TOKENS = 32768  # reply cap; the proxy reserves a call's worst-case cost against the daily quota
QUOTA_WAITS = 12  # a refused quota reservation is waited out this many times per message
QUOTA_SLEEP = 30  # seconds, give or take half
UNCAPPED = set()  # models whose provider refused the cap

ITEMS = {items}

if ITEM_LIMIT:
    ITEMS = dict(list(ITEMS.items())[:ITEM_LIMIT])

# %%
# Reply parser, inlined from memtrap/parse.py.
{parse_source}

# %%
# Scoring, inlined from memtrap/score.py.
{score_source}

# %%
def quota_refusal(exc: Exception) -> bool:
    """The model proxy reserves the worst-case cost of a call (its maximum
    output) against the daily quota and refuses the call while other calls
    hold the rest. The reservation is released when those calls end."""
    return "available quota" in str(exc)


def cap_refusal(exc: Exception) -> bool:
    text = str(exc)
    return not quota_refusal(exc) and any(
        name in text for name in ("max_tokens", "max_completion_tokens", "max_output_tokens")
    )


def ask(llm, message: str) -> str:
    """Send one user message; on an error, ask again for a reply to the same
    history instead of repeating the message."""
    sent = False
    errors = 0
    waits = 0
    while True:
        cap = {{}} if llm.name in UNCAPPED else {{"max_tokens": MAX_OUTPUT_TOKENS}}
        try:
            if not sent:
                sent = True
                return llm.prompt(message, extra_api_params=cap)
            temperature = 0 if getattr(llm, "support_temperature", False) else None
            return llm.respond(seed=0, temperature=temperature, **cap).content
        except Exception as exc:
            if quota_refusal(exc) and waits < QUOTA_WAITS:
                waits += 1
                time.sleep(QUOTA_SLEEP * (0.5 + random.random()))
                continue
            if cap and cap_refusal(exc):
                UNCAPPED.add(llm.name)
                continue
            errors += 1
            if errors >= ATTEMPTS:
                raise
            time.sleep(RETRY_SLEEP * errors)


@kbench.task(name={item_task_name!r}, store_task=False, store_run=False)
def memtrap_item(llm, item_id: str) -> dict:
    """One case under one condition and runtime version."""
    item = ITEMS[item_id]
    reply = ask(llm, item["prompt"])
    parsed = parse_response(reply, unit=item["unit"])
    retried = False
    if parsed is None:
        retried = True
        reply = ask(llm, REPAIR_MESSAGE)
        parsed = parse_response(reply, unit=item["unit"])
    row = score_response(item["case"], item["truth"], item["condition"], item["version"], parsed)
    row["item"] = item_id
    row["retried"] = retried
    kbench.assertions.assert_true(row["answer_ok"] == 1, expectation=item["expect_answer"])
    kbench.assertions.assert_true(row["mechanism_ok"] == 1, expectation=item["expect_mechanism"])
    kbench.assertions.assert_true(row["estimate_ok"] == 1, expectation=item["expect_estimate"])
    return row


@kbench.task(name={task_name!r}, description={summary!r})
def {function_name}(llm) -> float:
    """Mean case score over every item: (answer + estimate + mechanism) / 3."""
    data = pd.DataFrame({{"item_id": list(ITEMS)}}, index=list(ITEMS))
    runs = memtrap_item.evaluate(llm=[llm], evaluation_data=data, n_jobs=4, on_failure="continue")
    rows = [r.result for r in runs.completed_runs if isinstance(r.result, dict)]
    errored = len(ITEMS) - len(rows)
    summary = summarize(rows)
    kbench.assertions.assert_true(
        errored == 0, expectation=f"every item ran ({{errored}} of {{len(ITEMS)}} errored)"
    )
    kbench.assertions.assert_true(
        summary["parse_failures"] == 0,
        expectation=f"every reply parsed ({{summary['parse_failures']}} parse failures)",
    )
    return float(sum(r["case_score"] for r in rows) / len(ITEMS))


# %%
{function_name}.run(kbench.llm)

# %%
# %choose {function_name}
'''
